"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["81492"],{92875(e){e.exports=JSON.parse('{"id":"F356","slug":"bank-run-liquidity-shortfall","name":"Bank Run: Liquidity Shortfall and Fire-Sale Loss","subject":"Banking & Financial Institutions","section":"Banking","topic":"Bank runs and liquidity crises","level":"Intermediate","aliases":["bank runs and liquidity crises","fire sale","run threshold","liquid assets coverage"],"formula":{"latex":"\\\\text{Shortfall}=wD-L,\\\\quad \\\\text{Loss}=\\\\frac{h}{1-h}\\\\,\\\\text{Shortfall},\\\\quad w^{*}=\\\\frac{L+E(1-h)/h}{D}","also":[],"text":"Cash needed = withdrawal fraction x deposits; Shortfall = cash needed - liquid assets; Assets to sell (at book value) = shortfall / (1 - haircut); Fire-sale loss = book value sold - shortfall; Withdrawal fraction that wipes out equity = (liquid assets + equity x (1 - h) / h) / deposits"},"symbols":[{"symbol":"D","meaning":"Deposits (all withdrawable on demand)","unit":"money"},{"symbol":"L","meaning":"Liquid assets that can be paid out at full value","unit":"money"},{"symbol":"h","meaning":"Haircut: share of book value lost when selling illiquid loans in a hurry","unit":"percent"},{"symbol":"E","meaning":"Equity","unit":"money"},{"symbol":"w","meaning":"Share of deposits withdrawn","unit":"percent"}],"when_to_use":"Use it to see why a solvent bank can fail in a run. Deposits can leave at once while loans cannot be sold quickly, so a run forces sales at a discount, which eats equity and justifies more fear. The model has two thresholds: the withdrawal level the liquid assets cover, and the level at which fire-sale losses exceed equity. Central bank lending and deposit insurance work by removing the need to sell.","worked_example":{"problem":"A bank has liquid assets 150, loans 900 and equity 50, so deposits are 1,000. Depositors withdraw 30%. Loans can be sold at a 15% discount.","inputs":{"l":150,"a":900,"e":50,"w":30,"h":15},"steps":[{"label":"Deposits = liquid + loans - equity","working":"150+900-50","value":"1,000.00"},{"label":"Cash demanded = w x deposits","working":"0.3 x 1000","value":"300.00"},{"label":"Liquid assets available","working":"150","value":"150.00"},{"label":"Shortfall","working":"max(300-150, 0)","value":"150.00"},{"label":"Loans to sell (book value) = shortfall / (1 - h)","working":"150 / (1-0.15)","value":"176.47"},{"label":"Fire-sale loss","working":"176.471-150","value":"26.47"},{"label":"Equity after the loss","working":"50-26.4706","value":"23.53"},{"label":"Run the liquid assets can cover = L / D","working":"150 / 1000","value":"15.0%"},{"label":"Withdrawal share that wipes out equity","working":"(150+50 x (1-0.15) / 0.15) / 1000","value":"43.3%"}],"answer":"Deposits are 1,000.00. The run demands 300.00, but only 150.00 is liquid, leaving a shortfall of 150.00. Raising that cash means selling 176.47 of loans and realizing a loss of 26.47, which leaves equity of 23.53. Liquid assets alone cover runs of up to 15.0% of deposits, and the bank is wiped out if withdrawals reach 43.3%."},"calculator":{"available":true,"inputs":[{"id":"l","label":"Liquid assets","unit":"money","type":"number","default":150,"hint":""},{"id":"a","label":"Illiquid loans (book value)","unit":"money","type":"number","default":900,"hint":""},{"id":"e","label":"Equity","unit":"money","type":"number","default":50,"hint":""},{"id":"w","label":"Share of deposits withdrawn","unit":"%","type":"number","default":30,"hint":""},{"id":"h","label":"Fire-sale haircut","unit":"%","type":"number","default":15,"hint":""}],"checks":[{"expr":"l>=0 and a>0 and e>0 and h>0 and h<1","message":"Enter positive balances and a haircut between 0 and 100%."}],"steps":[{"id":"d","label":"Deposits = liquid + loans - equity","expr":"l+a-e","format":"money"},{"id":"wd","label":"Cash demanded = w x deposits","expr":"w*d","format":"money"},{"id":"l_","label":"Liquid assets available","expr":"l","format":"money"},{"id":"sh","label":"Shortfall","expr":"max(wd-l, 0)","format":"money"},{"id":"face","label":"Loans to sell (book value) = shortfall / (1 - h)","expr":"sh/(1-h)","format":"money"},{"id":"loss","label":"Fire-sale loss","expr":"face-sh","format":"money"},{"id":"eq2","label":"Equity after the loss","expr":"e-loss","format":"money"},{"id":"w1","label":"Run the liquid assets can cover = L / D","expr":"l/d","format":"pct1"},{"id":"wstar","label":"Withdrawal share that wipes out equity","expr":"(l+e*(1-h)/h)/d","format":"pct1"}],"results":["sh","loss","eq2","w1","wstar"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"d":1000,"wd":300,"l_":150,"sh":150,"face":176.47058823529412,"loss":26.470588235294116,"eq2":23.529411764705884,"w1":0.15,"wstar":0.43333333333333335}},"finder":{"finds":"How large a run a bank can survive","needs":"Liquid assets, loans, equity, run size, haircut"},"related":[{"slug":"deposit-insurance-coverage","name":"Deposit Insurance Coverage and Premium"},{"slug":"lcr-nsfr","name":"Basel Liquidity Ratios: LCR and NSFR"},{"slug":"liquidity-adjusted-var","name":"Liquidity-Adjusted VaR"}],"related_ids":["F354","F387","F386"],"group":"Money, banks and the economy","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mtext>Shortfall</mtext><mo>=</mo><mi>w</mi><mi>D</mi><mo>\u2212</mo><mi>L</mi><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><mtext>Loss</mtext><mo>=</mo><mfrac><mi>h</mi><mrow><mn>1</mn><mo>\u2212</mo><mi>h</mi></mrow></mfrac><mtext>\u2009</mtext><mtext>Shortfall</mtext><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><msup><mi>w</mi><mo lspace=\\"0em\\" rspace=\\"0em\\">\u2217</mo></msup><mo>=</mo><mfrac><mrow><mi>L</mi><mo>+</mo><mi>E</mi><mo stretchy=\\"false\\">(</mo><mn>1</mn><mo>\u2212</mo><mi>h</mi><mo stretchy=\\"false\\">)</mo><mi mathvariant=\\"normal\\">/</mi><mi>h</mi></mrow><mi>D</mi></mfrac></mrow><annotation encoding=\\"application/x-tex\\">\\\\text{Shortfall}=wD-L,\\\\quad \\\\text{Loss}=\\\\frac{h}{1-h}\\\\,\\\\text{Shortfall},\\\\quad w^{*}=\\\\frac{L+E(1-h)/h}{D}</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"bank-profitability-dupont","name":"Bank Profitability: Income Statement, ROA and ROE"},"next":{"slug":"irrbb-eve-nii","name":"Banking Book Interest Rate Risk: EVE and NII"},"lesson":null,"total":522}')}}]);